using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json;
using System.Text.Json.Nodes;
using Nitrogen.LanguageService;

namespace Nitrogen.Cli;

/// <summary>
/// <c>nitrogen generate palette --merge &lt;package.json&gt;</c>: writes the palette's semantic token types and scopes
/// into a VS Code extension that is not generated by Nitrogen (MotionDSL), replacing any earlier ones.
/// </summary>
internal static class PaletteCommand
{
    public const string Usage = "usage: nitrogen generate palette --merge <package.json>";

    public static async Task<int> RunAsync(IReadOnlyList<string> args, TextWriter output, CancellationToken cancel)
    {
        if (args is not [_, _, "--merge", var path])
        {
            await output.WriteLineAsync(Usage);
            return 2;
        }
        if (!File.Exists(path))
        {
            await output.WriteLineAsync($"error: no file '{path}'");
            return 2;
        }
        var package = JsonNode.Parse(await File.ReadAllTextAsync(path, cancel))!.AsObject();
        var contributes = package["contributes"] as JsonObject ?? new JsonObject();
        package["contributes"] = contributes;
        foreach (var (key, value) in Palette.VsCodeContributions().ToList())
            contributes[key] = value!.DeepClone();
        await File.WriteAllTextAsync(path, Json(package), cancel);
        return 0;
    }

    /// <summary>Two-space JSON with LF endings, characters such as … unescaped (as npm writes package.json).</summary>
    static string Json(JsonNode node)
    {
        using var stream = new MemoryStream();
        using (var writer = new Utf8JsonWriter(stream, new JsonWriterOptions { Indented = true, NewLine = "\n", Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping }))
            node.WriteTo(writer);
        return Encoding.UTF8.GetString(stream.ToArray()) + "\n";
    }
}
